// Pure-JavaScript SHA-256 implementation (no node:crypto, no external deps).
// Operates on Uint8Array and returns a 32-byte Uint8Array digest.

const K = new Uint32Array([
  0x428a2f98, 0x71374491, 0xb5c0fbcf, 0xe9b5dba5, 0x3956c25b, 0x59f111f1, 0x923f82a4, 0xab1c5ed5,
  0xd807aa98, 0x12835b01, 0x243185be, 0x550c7dc3, 0x72be5d74, 0x80deb1fe, 0x9bdc06a7, 0xc19bf174,
  0xe49b69c1, 0xefbe4786, 0x0fc19dc6, 0x240ca1cc, 0x2de92c6f, 0x4a7484aa, 0x5cb0a9dc, 0x76f988da,
  0x983e5152, 0xa831c66d, 0xb00327c8, 0xbf597fc7, 0xc6e00bf3, 0xd5a79147, 0x06ca6351, 0x14292967,
  0x27b70a85, 0x2e1b2138, 0x4d2c6dfc, 0x53380d13, 0x650a7354, 0x766a0abb, 0x81c2c92e, 0x92722c85,
  0xa2bfe8a1, 0xa81a664b, 0xc24b8b70, 0xc76c51a3, 0xd192e819, 0xd6990624, 0xf40e3585, 0x106aa070,
  0x19a4c116, 0x1e376c08, 0x2748774c, 0x34b0bcb5, 0x391c0cb3, 0x4ed8aa4a, 0x5b9cca4f, 0x682e6ff3,
  0x748f82ee, 0x78a5636f, 0x84c87814, 0x8cc70208, 0x90befffa, 0xa4506ceb, 0xbef9a3f7, 0xc67178f2,
]);

function rotr(x, n) {
  return ((x >>> n) | (x << (32 - n))) >>> 0;
}

export function sha256(message) {
  const msg = message instanceof Uint8Array ? message : new Uint8Array(message);
  const bitLenHi = Math.floor(msg.length / 0x20000000);
  const bitLenLo = (msg.length * 8) >>> 0;

  // Padded length: message + 0x80 + zeros + 8-byte big-endian length, multiple of 64.
  const paddedLen = (((msg.length + 9 + 63) >> 6) << 6);
  const buf = new Uint8Array(paddedLen);
  buf.set(msg);
  buf[msg.length] = 0x80;
  const dv = new DataView(buf.buffer);
  dv.setUint32(paddedLen - 8, bitLenHi, false);
  dv.setUint32(paddedLen - 4, bitLenLo, false);

  let h0 = 0x6a09e667, h1 = 0xbb67ae85, h2 = 0x3c6ef372, h3 = 0xa54ff53a;
  let h4 = 0x510e527f, h5 = 0x9b05688c, h6 = 0x1f83d9ab, h7 = 0x5be0cd19;

  const w = new Uint32Array(64);

  for (let offset = 0; offset < paddedLen; offset += 64) {
    for (let t = 0; t < 16; t++) {
      w[t] = dv.getUint32(offset + t * 4, false);
    }
    for (let t = 16; t < 64; t++) {
      const s0 = rotr(w[t - 15], 7) ^ rotr(w[t - 15], 18) ^ (w[t - 15] >>> 3);
      const s1 = rotr(w[t - 2], 17) ^ rotr(w[t - 2], 19) ^ (w[t - 2] >>> 10);
      w[t] = (w[t - 16] + s0 + w[t - 7] + s1) >>> 0;
    }

    let a = h0, b = h1, c = h2, d = h3, e = h4, f = h5, g = h6, h = h7;

    for (let t = 0; t < 64; t++) {
      const S1 = rotr(e, 6) ^ rotr(e, 11) ^ rotr(e, 25);
      const ch = (e & f) ^ (~e & g);
      const temp1 = (h + S1 + ch + K[t] + w[t]) >>> 0;
      const S0 = rotr(a, 2) ^ rotr(a, 13) ^ rotr(a, 22);
      const maj = (a & b) ^ (a & c) ^ (b & c);
      const temp2 = (S0 + maj) >>> 0;

      h = g; g = f; f = e;
      e = (d + temp1) >>> 0;
      d = c; c = b; b = a;
      a = (temp1 + temp2) >>> 0;
    }

    h0 = (h0 + a) >>> 0; h1 = (h1 + b) >>> 0; h2 = (h2 + c) >>> 0; h3 = (h3 + d) >>> 0;
    h4 = (h4 + e) >>> 0; h5 = (h5 + f) >>> 0; h6 = (h6 + g) >>> 0; h7 = (h7 + h) >>> 0;
  }

  const out = new Uint8Array(32);
  const odv = new DataView(out.buffer);
  odv.setUint32(0, h0, false); odv.setUint32(4, h1, false);
  odv.setUint32(8, h2, false); odv.setUint32(12, h3, false);
  odv.setUint32(16, h4, false); odv.setUint32(20, h5, false);
  odv.setUint32(24, h6, false); odv.setUint32(28, h7, false);
  return out;
}

// HMAC-SHA256 built on the pure-JS SHA-256 from ./sha256.mjs (RFC 2104).

import { sha256 } from './sha256.mjs';

const BLOCK_SIZE = 64;

export function hmacSha256(key, message) {
  let k = key instanceof Uint8Array ? key : new Uint8Array(key);
  if (k.length > BLOCK_SIZE) {
    k = sha256(k);
  }
  const ipad = new Uint8Array(BLOCK_SIZE);
  const opad = new Uint8Array(BLOCK_SIZE);
  for (let i = 0; i < BLOCK_SIZE; i++) {
    const b = i < k.length ? k[i] : 0;
    ipad[i] = b ^ 0x36;
    opad[i] = b ^ 0x5c;
  }
  const inner = new Uint8Array(BLOCK_SIZE + message.length);
  inner.set(ipad);
  inner.set(message, BLOCK_SIZE);
  const innerHash = sha256(inner);

  const outer = new Uint8Array(BLOCK_SIZE + innerHash.length);
  outer.set(opad);
  outer.set(innerHash, BLOCK_SIZE);
  return sha256(outer);
}

// Base64url encoding (RFC 7515, no padding) over Uint8Array,
// matching Python's base64.urlsafe_b64encode(...).rstrip(b'=').

const ALPHABET = 'ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-_';

export function base64urlEncode(bytes) {
  const data = bytes instanceof Uint8Array ? bytes : new Uint8Array(bytes);
  let out = '';
  for (let i = 0; i < data.length; i += 3) {
    const b0 = data[i];
    const b1 = i + 1 < data.length ? data[i + 1] : 0;
    const b2 = i + 2 < data.length ? data[i + 2] : 0;
    out += ALPHABET[b0 >> 2];
    out += ALPHABET[((b0 & 0x03) << 4) | (b1 >> 4)];
    if (i + 1 < data.length) out += ALPHABET[((b1 & 0x0f) << 2) | (b2 >> 6)];
    if (i + 2 < data.length) out += ALPHABET[b2 & 0x3f];
  }
  return out;
}

// Python-compatible json.dumps(value, ensure_ascii=True, separators=(',', ':'))
// for the subset of values needed here (objects with string keys, string values).
// String escaping mirrors CPython's json encoder: escape '"' and '\\', plus any
// character outside 0x20..0x7E; control chars use short escapes where Python
// defines them (\b \t \n \f \r), otherwise \uXXXX with lowercase hex;
// non-BMP code points are emitted as UTF-16 surrogate pair escapes.

function hex4(codeUnit) {
  return '\\u' + codeUnit.toString(16).padStart(4, '0');
}

export function dumpsString(s) {
  let out = '"';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code === 0x22) {
      out += '\\"';
    } else if (code === 0x5c) {
      out += '\\\\';
    } else if (code >= 0x20 && code <= 0x7e) {
      out += s[i];
    } else if (code === 0x08) {
      out += '\\b';
    } else if (code === 0x09) {
      out += '\\t';
    } else if (code === 0x0a) {
      out += '\\n';
    } else if (code === 0x0c) {
      out += '\\f';
    } else if (code === 0x0d) {
      out += '\\r';
    } else {
      out += hex4(code);
    }
  }
  return out + '"';
}

export function dumpsObject(obj) {
  const parts = [];
  for (const key of Object.keys(obj)) {
    parts.push(dumpsString(key) + ':' + dumpsValue(obj[key]));
  }
  return '{' + parts.join(',') + '}';
}

export function dumpsValue(value) {
  if (typeof value === 'string') return dumpsString(value);
  if (value !== null && typeof value === 'object') return dumpsObject(value);
  throw new TypeError('unsupported value type for pyjson.dumps');
}

// Minimal reimplementation of python-jose's jwt.encode with the default
// algorithm HS256: base64url(header) + '.' + base64url(payload) + '.' +
// base64url(HMAC-SHA256(secret, signingInput)).

import { hmacSha256 } from './hmacSha256.mjs';
import { base64urlEncode } from './base64url.mjs';
import { dumpsObject } from './pyjson.mjs';

const encoder = new TextEncoder();

export function encode(claims, key) {
  const header = { alg: 'HS256', typ: 'JWT' };
  const segments = [
    base64urlEncode(encoder.encode(dumpsObject(header))),
    base64urlEncode(encoder.encode(dumpsObject(claims))),
  ];
  const signingInput = segments.join('.');
  const signature = hmacSha256(encoder.encode(key), encoder.encode(signingInput));
  segments.push(base64urlEncode(signature));
  return segments.join('.');
}

// Minimal argparse-compatible parser for this script's interface:
// a single required string option --payload. Supports "--payload value" and
// "--payload=value", plus -h/--help. Errors print usage to stderr and exit 2,
// matching Python argparse behavior.

function usage(prog) {
  return `usage: ${prog} [-h] --payload PAYLOAD`;
}

export function parseArgs(argv, prog) {
  const args = { payload: undefined };

  for (let i = 0; i < argv.length; i++) {
    const arg = argv[i];
    if (arg === '-h' || arg === '--help') {
      console.log(usage(prog));
      console.log('');
      console.log('options:');
      console.log('  -h, --help         show this help message and exit');
      console.log('  --payload PAYLOAD');
      process.exit(0);
    } else if (arg === '--payload') {
      if (i + 1 >= argv.length) {
        process.stderr.write(usage(prog) + '\n');
        process.stderr.write(`${prog}: error: argument --payload: expected one argument\n`);
        process.exit(2);
      }
      args.payload = argv[++i];
    } else if (arg.startsWith('--payload=')) {
      args.payload = arg.slice('--payload='.length);
    } else {
      process.stderr.write(usage(prog) + '\n');
      process.stderr.write(`${prog}: error: unrecognized arguments: ${arg}\n`);
      process.exit(2);
    }
  }

  if (args.payload === undefined) {
    process.stderr.write(usage(prog) + '\n');
    process.stderr.write(`${prog}: error: the following arguments are required: --payload\n`);
    process.exit(2);
  }

  return args;
}

// Node.js (ESM) port of /workspace/dataset/test1.py
// Encodes {"data": <payload>} as a JWT signed with HS256 and prints it.

import { basename } from 'node:path';
import { encode } from './lib/jwt.mjs';
import { parseArgs } from './lib/argparse.mjs';

const prog = basename(process.argv[1] || 'test1.mjs');
const args = parseArgs(process.argv.slice(2), prog);

// jwt.encode: encode the payload (a dict) as a JWT token with default
// algorithm HS256; a secret is required to sign.
const secret = 'my_secret_key';
const token = encode({ data: args.payload }, secret);
console.log(token);
